namespace Inventory;

/// <summary>
/// Applies stock adjustments, makes reorder decisions, allocates zones and
/// places supplier orders.
/// </summary>
public sealed class StockController
{
    private readonly StockAdjustmentOperations _adjustments;
    private readonly StockReorderPolicy _reorderPolicy;
    private readonly StockZoneAllocator _zoneAllocator;
    private readonly StockSupplierOrdering _supplierOrdering;
    private readonly StockAnalysis _analysis;

    public StockController(ISupplier supplier)
    {
        _adjustments = new StockAdjustmentOperations();
        _reorderPolicy = new StockReorderPolicy();
        _zoneAllocator = new StockZoneAllocator();
        _supplierOrdering = new StockSupplierOrdering(supplier, _reorderPolicy);
        _analysis = new StockAnalysis(_reorderPolicy, _zoneAllocator);
    }

    public int AdjustStock(StockItem item, int delta) =>
        _adjustments.AdjustStock(item, delta);

    public int Available(StockItem item) =>
        _adjustments.Available(item);

    public int MovementCount => _adjustments.MovementCount;

    public bool NeedsReorder(StockItem item) =>
        _reorderPolicy.NeedsReorder(item);

    public int ReorderQuantity(StockItem item) =>
        _reorderPolicy.ReorderQuantity(item);

    public int ResolveThreshold(string sku) =>
        _reorderPolicy.ResolveThreshold(sku);

    public string AllocateToZone(StockItem item, Warehouse warehouse) =>
        _zoneAllocator.AllocateToZone(item, warehouse);

    public int ZoneSpare(Warehouse warehouse) =>
        _zoneAllocator.ZoneSpare(warehouse);

    public bool PlaceReorder(StockItem item) =>
        _supplierOrdering.PlaceReorder(item);

    public bool ConfirmDelivery(StockItem item, int delivered) =>
        _supplierOrdering.ConfirmDelivery(item, delivered);

    public string Classify(StockItem item) =>
        _analysis.Classify(item);

    public IReadOnlyList<string> AuditStock(StockItem item, Warehouse warehouse) =>
        _analysis.AuditStock(item, warehouse);

    public int ForecastDepletion(StockItem item, int dailyDemand) =>
        _analysis.ForecastDepletion(item, dailyDemand);
}

internal sealed class StockAdjustmentOperations
{
    private readonly List<string> _movements = new();

    internal int AdjustStock(StockItem item, int delta)
    {
        if (delta == 0)
            return item.OnHand;
        if (delta < 0 && item.OnHand + delta < 0)
            return item.OnHand;

        item.OnHand += delta;
        if (delta > 0)
            _movements.Add($"IN {item.Sku} {delta}");
        else
            _movements.Add($"OUT {item.Sku} {-delta}");

        if (item.OnHand < item.Reserved)
            _movements.Add($"WARN {item.Sku} oversold");

        return item.OnHand;
    }

    internal int Available(StockItem item)
    {
        int free = item.OnHand - item.Reserved;
        if (free < 0)
            return 0;
        return free;
    }

    internal int MovementCount => _movements.Count;
}

internal sealed class StockReorderPolicy
{
    private readonly Dictionary<string, int> _reorderThresholds = new(StringComparer.Ordinal);
    private readonly int _defaultReorder = 20;

    internal bool NeedsReorder(StockItem item)
    {
        if (item.Sku.Length == 0)
            return false;

        int available = item.OnHand - item.Reserved;
        var threshold = ResolveThreshold(item.Sku);
        if (item.ReorderPoint > 0)
            return available <= item.ReorderPoint;
        return available <= threshold;
    }

    internal int ReorderQuantity(StockItem item)
    {
        if (!NeedsReorder(item))
            return 0;

        int available = item.OnHand - item.Reserved;
        int target = item.ReorderPoint > 0 ? item.ReorderPoint * 2 : _defaultReorder * 2;
        int qty = target - available;
        if (qty < 0)
            qty = 0;
        else if (qty < 5)
            qty = 5;
        return qty;
    }

    internal int ResolveThreshold(string sku)
    {
        if (string.IsNullOrEmpty(sku))
            return _defaultReorder;
        if (_reorderThresholds.TryGetValue(sku, out var threshold))
            return threshold;
        return _defaultReorder;
    }
}

internal sealed class StockZoneAllocator
{
    private readonly Dictionary<string, int> _zoneUsage = new(StringComparer.Ordinal);

    internal string AllocateToZone(StockItem item, Warehouse warehouse)
    {
        if (warehouse.Zones.Count == 0)
            return "no zones";

        int need = item.OnHand - item.Reserved;
        if (need <= 0)
            return "nothing to place";

        foreach (var zone in warehouse.Zones)
        {
            var used = UsageFor(zone.Name);
            int spare = zone.Capacity - used;
            if (spare <= 0)
                continue;

            int place = need > spare ? spare : need;
            _zoneUsage[zone.Name] = used + place;
            need -= place;
            if (need <= 0)
                return $"placed in {zone.Name}";
        }

        return "overflow";
    }

    internal int ZoneSpare(Warehouse warehouse)
    {
        int spare = 0;
        foreach (var zone in warehouse.Zones)
        {
            var used = UsageFor(zone.Name);
            if (zone.Capacity > used)
                spare += zone.Capacity - used;
        }
        return spare;
    }

    internal int UsageFor(string zoneName) =>
        _zoneUsage.TryGetValue(zoneName, out var usage) ? usage : 0;
}

internal sealed class StockSupplierOrdering
{
    private readonly ISupplier _supplier;
    private readonly StockReorderPolicy _reorderPolicy;
    private readonly Dictionary<string, int> _pending = new(StringComparer.Ordinal);

    internal StockSupplierOrdering(ISupplier supplier, StockReorderPolicy reorderPolicy)
    {
        _supplier = supplier;
        _reorderPolicy = reorderPolicy;
    }

    internal bool PlaceReorder(StockItem item)
    {
        var qty = _reorderPolicy.ReorderQuantity(item);
        if (qty <= 0)
            return false;
        if (_pending.TryGetValue(item.Sku, out var existing) && existing >= qty)
            return false;

        var accepted = _supplier.PlaceOrder(item.Sku, qty);
        if (accepted)
            _pending[item.Sku] = qty;
        return accepted;
    }

    internal bool ConfirmDelivery(StockItem item, int delivered)
    {
        if (delivered <= 0)
            return false;
        if (!_pending.TryGetValue(item.Sku, out var qty))
            return false;

        item.OnHand += delivered;
        if (delivered >= qty)
            _pending.Remove(item.Sku);
        else
            _pending[item.Sku] = qty - delivered;
        return true;
    }
}

internal sealed class StockAnalysis
{
    private readonly StockReorderPolicy _reorderPolicy;
    private readonly StockZoneAllocator _zoneAllocator;

    internal StockAnalysis(StockReorderPolicy reorderPolicy, StockZoneAllocator zoneAllocator)
    {
        _reorderPolicy = reorderPolicy;
        _zoneAllocator = zoneAllocator;
    }

    internal string Classify(StockItem item)
    {
        int available = item.OnHand - item.Reserved;
        if (available < 0)
            return "oversold";
        if (available == 0)
            return "out";
        if (item.ReorderPoint > 0 && available <= item.ReorderPoint)
            return "low";
        if (available > item.ReorderPoint * 5)
            return "excess";
        return "ok";
    }

    internal IReadOnlyList<string> AuditStock(StockItem item, Warehouse warehouse)
    {
        var findings = new List<string>();
        if (item.OnHand < 0)
            findings.Add($"{item.Sku}:negative-onhand");
        if (item.Reserved < 0)
            findings.Add($"{item.Sku}:negative-reserve");
        if (item.OnHand < item.Reserved)
            findings.Add($"{item.Sku}:oversold");

        foreach (var zone in warehouse.Zones)
        {
            var used = _zoneAllocator.UsageFor(zone.Name);
            if (used > zone.Capacity)
                findings.Add($"{zone.Name}:over-capacity");
            else if (used < 0)
                findings.Add($"{zone.Name}:negative-usage");
        }

        if (findings.Count == 0)
            findings.Add("clean");
        return findings;
    }

    internal int ForecastDepletion(StockItem item, int dailyDemand)
    {
        if (dailyDemand <= 0)
            return -1;

        int available = item.OnHand - item.Reserved;
        if (available <= 0)
            return 0;

        int days = available / dailyDemand;
        if (item.ReorderPoint > 0 && available <= item.ReorderPoint)
            return 0;
        if (days > 365)
            return 365;

        var threshold = _reorderPolicy.ResolveThreshold(item.Sku);
        if (threshold > 0 && available <= threshold)
            return 1;
        if (days < 7)
            return days;
        return days;
    }
}
